const ПОРЕДЕН = { 21: 'ва', 22: 'ра', 27: 'ма', 28: 'ма', 31: 'ва', 32: 'ра', 37: 'ма', 38: 'ма', 41: 'ва', 42: 'ра' };
const формиЗа = N => {
  const к = [
    'на ' + N + ' седмица съм', 'в ' + N + ' седмица съм', N + ' седмица съм', N + ' седмица бременност',
    'бременна в ' + N + ' седмица', N + ' та седмица', N + ' гс', N + ' седмица какво става',
    'какво става в ' + N + ' седмица', 'na ' + N + ' sedmica sam',
    N + ' sedmica sam',
    N + ' седмица бременна', N + ' седмици бременна', 'на ' + N + ' седмици съм', N + ' г с',
    'съм на ' + N + ' седмица', 'съм в ' + N + ' седмица', 'съм ' + N + ' седмица',
    N + ' седмица какво', 'с бебето на ' + N + ' седмица', 'с бебето в ' + N + ' седмица'
  ];
  if (ПОРЕДЕН[N]) к.push(N + ' ' + ПОРЕДЕН[N] + ' седмица');
  // br-sedmici вече държи „на/в N седмица съм“ и „имам N седмици“ за 37–41 (гейтът ги отказва).
  // За тях — по-дълга фраза, която бие неговия ключ само когато майката пита „какво“.
  if (N >= 37 && N <= 41) {
    const заети = ['на ' + N + ' седмица съм', 'в ' + N + ' седмица съм'];
    return к.filter(x => !заети.includes(x)).concat(['на ' + N + ' седмица съм какво', 'в ' + N + ' седмица съм какво']);
  }
  к.push('имам ' + N + ' седмици');
  return к;
};
