const карти = [], статии = [];
for (const д of ДВОЙКИ) {
  const id = 'zn7b-sedmica-' + д.a + '-' + д.b;
  const keys = [];
  const махни = ВАРИАНТ === 'B' ? НАДМНОЖЕСТВА(д.a).concat(НАДМНОЖЕСТВА(д.b)) : [];
  for (const к of формиЗа(д.a).concat(формиЗа(д.b), д.tema || [], ИНДЕКСНИ(д.a, д.b))) if (!keys.includes(к) && !махни.includes(к)) keys.push(к);
  карти.push({ id, room: 'Бременност', 'от': -9, 'до': 0, title: д.title, core: д.core, tip: д.tip, follow: д.follow, keys, chips: д.chips });
  статии.push({ karta: id, t: д.st.t, e: д.st.e, s: д.st.s, k: д.st.k, c: д.st.c, body: д.st.body });
}

// ── проверки (печатат, не спират) ──
const думи = s => String(s).trim().split(/\s+/).length;
let проблеми = 0;
const кажи = (ок, т) => { if (!ок) { проблеми++; console.log('🔴 ' + т); } };
for (const к of карти) {
  const т = [к.title, к.core, к.tip, к.follow].join('\n');
  кажи(!/["']/.test(т), к.id + ': права кавичка в текста');
  кажи(!/["']/.test(к.keys.join(' ')), к.id + ': права кавичка в ключ');
  кажи(!/\d+\s*(мг|мл|mg|ml)/i.test(т), к.id + ': доза');
  кажи(!/(гарантиран|100\s*%|напълно безопасно|няма никакъв риск)/i.test(т), к.id + ': обещание');
  кажи(думи(к.core) >= 90 && думи(к.core) <= 170, к.id + ': core ' + думи(к.core) + ' думи');
  кажи(/^🚨/.test(к.follow), к.id + ': follow не започва с 🚨');
  кажи(/112/.test(к.follow), к.id + ': follow без 112');
  кажи(!к.keys.some(x => /[А-Я]/.test(x)), к.id + ': главна буква в ключ');
  console.log('   ' + к.id.padEnd(22) + ' core ' + думи(к.core) + ' д. · ключове ' + к.keys.length + ' · латиница ' + к.keys.filter(x => /[a-z]/.test(x)).length);
}
for (const с of статии) {
  const б = с.body;
  кажи(!/["']/.test(б + с.t + с.s + с.k), с.karta + ': права кавичка в статията');
  кажи(!/\r/.test(б), с.karta + ': \\r');
  кажи(б.startsWith('## '), с.karta + ': тялото не започва с ##');
  кажи((б.match(/^## /gm) || []).length >= 3, с.karta + ': под 3 раздела');
  кажи(думи(б) >= 300 && думи(б) <= 600, с.karta + ': тяло ' + думи(б) + ' думи');
  кажи(б.trim().split('\n').pop() === 'Записките не заменят преглед.', с.karta + ': последен ред');
  кажи(с.s.length <= 200, с.karta + ': резюме ' + с.s.length + ' знака');
  кажи(!/\d+\s*(мг|мл|mg|ml)/i.test(б), с.karta + ': доза в статията');
  for (const ред of б.split('\n')) if (/🚨/.test(ред)) кажи(/^(- )?🚨/.test(ред), с.karta + ': 🚨 не е отпред: ' + ред.slice(0, 50));
  console.log('   ' + с.karta.padEnd(22) + ' статия ' + думи(б) + ' д. · резюме ' + с.s.length + ' зн. · ' + с.c);
}
if (ВАРИАНТ === 'B') {
  fs.writeFileSync('dev/znanie/vlivane/zn7b_karti_B.json', JSON.stringify(карти, null, 1), 'utf8');
  console.log('ВАРИАНТ B → dev/znanie/vlivane/zn7b_karti_B.json (стажът НЕ е пипнат)');
} else {
  fs.writeFileSync('dev/nahodki/karti_zn7b.json', JSON.stringify(карти, null, 1), 'utf8');
  fs.writeFileSync('dev/nahodki/statii_zn7b.json', JSON.stringify(статии, null, 1), 'utf8');
}
console.log('\nкарти ' + карти.length + ' · статии ' + статии.length + ' · проблеми ' + проблеми);
